import sys

def is_subseq(t, s, l, r):
    """Check if t is a subsequence of s with substring [l, r] removed."""
    i = 0  # pointer for t
    n = len(s)
    m = len(t)
    if m == 0:
        return True
    for j in range(n):
        if l <= j <= r:
            continue
        if i < m and s[j] == t[i]:
            i += 1
    return i == m

def solve():
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()
    n = len(s)
    m = len(t)

    max_len = 0

    for start in range(n):
        for end in range(start, n):
            # remove s[start:end+1]
            if is_subseq(t, s, start, end):
                max_len = max(max_len, end - start + 1)

    print(max_len)

if __name__ == "__main__":
    solve()
"}

