import sys

def is_valid(n, m, grid, is_horizontal):
    """Check if the grid is a valid flag with stripes"""

    if is_horizontal:
        if n % 3 != 0:
            return False
        stripe_height = n // 3

        # Check first stripe
        first_color = grid[0][0]
        for i in range(stripe_height):
            for j in range(m):
                if grid[i][j] != first_color:
                    return False

        # Check second stripe
        second_color = grid[stripe_height][0]
        for i in range(stripe_height, 2 * stripe_height):
            for j in range(m):
                if grid[i][j] != second_color:
                    return False

        # Check third stripe
        third_color = grid[2 * stripe_height][0]
        for i in range(2 * stripe_height, n):
            for j in range(m):
                if grid[i][j] != third_color:
                    return False

        # Check all three colors are present
        return first_color != second_color and second_color != third_color and first_color != third_color
    else:
        if m % 3 != 0:
            return False
        stripe_width = m // 3

        # Check first stripe
        first_color = grid[0][0]
        for i in range(n):
            for j in range(stripe_width):
                if grid[i][j] != first_color:
                    return False

        # Check second stripe
        second_color = grid[0][stripe_width]
        for i in range(n):
            for j in range(stripe_width, 2 * stripe_width):
                if grid[i][j] != second_color:
                    return False

        # Check third stripe
        third_color = grid[0][2 * stripe_width]
        for i in range(n):
            for j in range(2 * stripe_width, m):
                if grid[i][j] != third_color:
                    return False

        # Check all three colors are present
        return first_color != second_color and second_color != third_color and first_color != third_color

def solve() -> None:
    """Solve the problem"""
    data = sys.stdin.read().strip().split()

    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    grid = data[2:2+n]

    # Check horizontal stripes
    if is_valid(n, m, grid, True):
        print("YES")
        return

    # Check vertical stripes
    if is_valid(n, m, grid, False):
        print("YES")
        return

    print("NO")

if __name__ == "__main__":
    solve()
"}

