    sum_of_digits = 0
    for r in range(l, n):
        sum_of_digits += s[r]

        # Compute digital root
        dr = sum_of_digits % mod
        if dr == 0:
            if sum_of_digits != 0:
                dr = mod  # d(x) = k-1
            else:
                dr = 0   # d(0) = 0

        if dr == b:
            count += 1

print(count)
