# For each position, try to place the smallest possible number that works
# A number can be placed if:
# 1. It hasn't been placed yet
# 2. It's either:
#    a) In the original array and has a count > 1 (overused, so we need to change it)
#    b) In the original array and has a count == 1 (not overused, can keep it)
#    c) Not in the original array (needs to be added)

for i in range(n):
    current = a[i]

    # Try to keep current if it's valid
    if 1 <= current <= n and (count[current] > 1 or count[current] == 1):
        # We can keep this number if it's not overused (count == 1)
        # If it's overused (count > 1), we need to change it anyway
        if count[current] == 1:
            result.append(current)
            count[current] = 0
        else:
            # Overused, so we need to change it
            # Try to place the smallest available number
            for num in range(1, n + 1):
                if count[num] > 0:
                    result.append(num)
                    count[num] = 0
                    break
