def solve():
    n, m, k = map(int, input().split())
    a = list(map(int, input().split()))

    # Create adjacency matrix for rules
    c = [[0] * (n + 1) for _ in range(n + 1)]

    for _ in range(k):
        x, y, val = map(int, input().split())
        c[x][y] = val

    # dp[i][j] = max satisfaction for a sequence of length i ending with dish j
    # We need to track which dishes have been used
    # Since m <= 18, we can use bitmask

    # Initialize DP
    dp = [{} for _ in range(m + 1)]  # dp[length][last_dish] = max_satisfaction

    # Base case: sequences of length 1
    for i in range(1, n + 1):
        dp[1][(1 << (i - 1))] = a[i - 1]

    # Fill DP
    for length in range(2, m + 1):
        for last_mask, last_satisfaction in dp[length - 1].items():
            last_dish = -1
            for i in range(n):
                if (last_mask >> i) & 1:
                    last_dish = i + 1
                    break

            for new_dish in range(1, n + 1):
                if not (last_mask >> (new_dish - 1)) & 1:
                    new_mask = last_mask | (1 << (new_dish - 1))

                    # Check if there's a rule for last_dish before new_dish
                    extra = c[last_dish][new_dish]

                    # Update dp
                    new_satisfaction = last_satisfaction + a[new_dish - 1] + extra

                    if new_dish not in dp[length] or new_satisfaction > dp[length][new_dish]:
                        dp[length][new_dish] = new_satisfaction

    # Find maximum satisfaction for sequences of length m
    max_satisfaction = 0
    for satisfaction in dp[m].values():
        if satisfaction > max_satisfaction:
            max_satisfaction = satisfaction

    print(max_satisfaction)

if __name__ == "__main__":
    solve()
