        visited_a.add(a)

        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if neighbor not in visited_a:
                    visited_a.add(neighbor)
                    queue.append(neighbor)

        # Find vertices that can reach b but not a
        visited_b = set()
        queue = [b]
        visited_b.add(b)

        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if neighbor not in visited_b:
                    visited_b.add(neighbor)
                    queue.append(neighbor)

        # Build set S
        S = set()
        for vertex in visited_a:
            if vertex != b:
                S.add(vertex)
        for vertex in visited_b:
            if vertex != a:
                S.add(vertex)

        # Count unordered pairs
        count = len(S)
        print(count * (count - 1) // 2)

