    data = sys.stdin.read().strip().split()
    ptr = 0
    n, m, q = int(data[ptr]), int(data[ptr+1]), int(data[ptr+2])
    ptr += 3

    a = list(map(int, data[ptr:ptr+n]))
    ptr += n

    b = list(map(int, data[ptr:ptr+m]))
    ptr += m

    # Compute S = (a1 - a2 + a3 - a4 + ... + (-1)^{n-1}an) - (b2 - b3 + b4 - b5 + ... + (-1)^{n+1}b_{n+1})
    S = 0
    for i in range(n):
        # a terms: +a1 -a2 +a3 -a4 +a5 ...
        a_term = a[i]
        if i % 2 == 0:
            S += a_term
        else:
            S -= a_term

        # b terms: -b2 +b3 -b4 +b5 ...
        if i % 2 == 0:
            S -= b[i+1]  # because we need -b2 +b3 -b4 +b5 ...
        else:
            S += b[i+1]

    # Find minimum value over j in [0, m-n]
    # f(j) = |S + j|
    # minimum at j = -S if possible

    if n % 2 == 0:
        print(abs(S))
    else:
        if -S >= 0 and -S <= m - n:
            print(0)
        else:
            if -S < 0:
                min_val = abs(S)
            else:
                min_val = abs(S - (m - n))
