def find_blocks(grid):
    """Identify all non-black blocks in the grid"""
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    blocks = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '0' and not visited[r][c]:
                # Find entire block
                color = grid[r][c]
                block = []
                for nr in range(r, rows):
                    for nc in range(c, cols):
                        if grid[nr][nc] == color:
                            block.append((nr, nc))
                            visited[nr][nc] = True
                        else:
                            break
                    else:
                        continue
                    break

                # Find top-left corner
                top_left = (r, c)
                bottom_right = (block[-1][0], block[-1][1])

                # Determine which corner is the "corner" based on DP (right) initially
                # For DP = right, we care about the leftmost edge
                # So the top-left corner of the block

                blocks.append({
                    "color": color,
                    "top_left": top_left,
                    "bottom_right": bottom_right,
                    "rect": block,
                    "adjacent": []
                })
    return blocks

def find_adjacent_blocks(block, blocks):
    """Find adjacent blocks for a given block"""
    r1, c1 = block["top_left"]
    r2, c2 = block["bottom_right"]

    for other in blocks:
