def parse_paths(paths):
    from collections import defaultdict

    # Maps disk to folder tree
    disks = defaultdict(lambda: {'root': {'subfolders': {}, 'files': 0, 'total_files': 0}})

    for path in paths:
        # Extract disk name
        parts = path.split('\')
        disk_name = parts[0][0]  # The disk is the first character after the colon

        # Extract folder path and file name
        if len(parts) < 2:
            continue

        folders_part = parts[1:-1]
        file_name = parts[-1]

        # Build folder structure
        current = disks[disk_name]['root']

        # Process each folder except the last one (the last folder is where the file is)
        for i, folder in enumerate(folders_part):
            if folder not in current['subfolders']:
                current['subfolders'][folder] = {'subfolders': {}, 'files': 0, 'total_files': 0}
            current = current['subfolders'][folder]
            current['total_files'] += 1

            # Count this folder as a subfolder of its parent
            parent = current
            while parent['total_files'] > 0 and parent['subfolders']:
                parent = parent['subfolders'].values()[0]  # Go up to the parent
                parent['subfolders'][folder] = {'subfolders': {}, 'files': 0, 'total_files': 0}

    # Find max subfolders and max files
    max_subfolders = 0
    max_files = 0

    for disk in disks.values():
        for node in disk['root'].values():
            max_subfolders = max(max_subfolders, len(node['subfolders']))
            max_files = max(max_files, node['total_files'])

    return max_subfolders, max_files

