    # Precompute positions for each element
    pos = [[] for _ in range(n + 1)]
    for i in range(m):
        pos[a[i]].append(i)

    # Binary search for first element >= l
    def find_first_ge(arr, l):
        if not arr:
            return -1
        low, high = 0, len(arr) - 1
        res = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] >= l:
                res = arr[mid]
                high = mid - 1
            else:
                low = mid + 1
        return res

    # Binary search for last element <= r
    def find_last_le(arr, r):
        if not arr:
            return -1
        low, high = 0, len(arr) - 1
        res = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] <= r:
                res = arr[mid]
                low = mid + 1
            else:
                high = mid - 1
        return res

    # Check if a subsegment [l, r] contains a subsequence that is a cyclic shift of p
    def contains_cyclic_shift(l, r):
        # Check if all elements of p are in the subsegment
        for i in range(n):
            if not pos[p[i]] or find_last_le(pos[p[i]], r) == -1 or find_first_ge(pos[p[i]], l) == -1:
                return False

        # Try to match the original permutation
        idx = l - 1
