    m = int(data[1+n])
    b = list(map(int, data[1+n+1:1+n+1+m]))

    # Calculate initial sums
    sum_a = sum(a)
    sum_b = sum(b)

    # Try 0 swaps
    min_diff = abs(sum_a - sum_b)
    best_swaps = []

    # Try 1 swap
    for i in range(n):
        for j in range(m):
            # Swap a[i] and b[j]
            new_sum_a = sum_a - a[i] + b[j]
            new_sum_b = sum_b - b[j] + a[i]
            diff = abs(new_sum_a - new_sum_b)

            if diff < min_diff:
                min_diff = diff
                best_swaps = [[i+1, j+1]]  # 1-indexed
            elif diff == min_diff:
                # If equal, keep the one with smallest first index, then second index
                if not best_swaps or best_swaps[0][0] > i+1:
