import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n, m, k = int(data[idx]), int(data[idx+1]), int(data[idx+2])
    idx += 3

    a = [int(data[idx + i]) for i in range(n)]
    idx += n

    rules = {}
    for _ in range(k):
        x = int(data[idx]) - 1
        y = int(data[idx+1]) - 1
        c = int(data[idx+2])
        rules[(x, y)] = c
        idx += 3

    # dp[mask][last] = maximum satisfaction
    # mask: set of dishes eaten so far
    # last: index of the last dish eaten
    INF = -10**18
    dp = [[INF] * n for _ in range(1 << n)]

    # Initial states: eat one dish
    for i in range(n):
        dp[1 << i][i] = a[i]

    # Build up to m dishes
    for dishes_eaten in range(1, m):
        for mask in range(1, 1 << n):
            if bin(mask).count('1') != dishes_eaten:
                continue

            # Find the last dish
            last = -1
            for i in range(n):
                if mask & (1 << i):
                    last = i

            if last == -1:
                continue

            # Get current max satisfaction
            current_max = dp[mask][last]
            if current_max == INF:
                continue

            # Try adding a new dish
            for new_dish in range(n):
                if not (mask & (1 << new_dish)):
                    new_mask = mask | (1 << new_dish)

                    # Add the dish's satisfaction
                    new_satisfaction = current_max + a[new_dish]

                    # Add any rule that applies (last -> new_dish)
                    if (last, new_dish) in rules:
                        new_satisfaction += rules[(last, new_dish)]

                    if dp[new_mask][new_dish] < new_satisfaction:
                        dp[new_mask][new_dish] = new_satisfaction

    # Find the best state with exactly m dishes
    best = 0
    for i in range(n):
        best = max(best, dp[(1 << n) - 1][i])

    print(best)

if __name__ == '__main__':
    solve()
