def solve():
    n = int(input())
    if n == 2:
        # Only one pair, should be (1, 2)
        a, b = map(int, input().split())
        if a == 1 and b == 2:
            print("YES")
            print(1, 2)
        else:
            print("NO")
        return

    pairs = []
    for _ in range(n - 1):
        a, b = map(int, input().split())
        pairs.append((a, b))

    # Find the edge that connects vertex n to its parent
    # We need to find a pair where one element is n
    max_index = n

    # Find the max of the other component
    # We need to find a pair where one element is n
    # The other element is the max of the subtree that doesn't contain n
    other_max = -1

    # For each pair, check if it could be the one involving n
    for a, b in pairs:
        if a == max_index:
            other_max = b
            break
        if b == max_index:
            other_max = a
            break

    if other_max == -1:
        print("NO")
        return

    # Now, we know max_index is connected to other_max
    print("YES")
    print(other_max, max_index)

    # Remove all pairs that involve max_index or other_max
    remaining_pairs = []
    for a, b in pairs:
        if a != max_index and b != max_index and a != other_max and b != other_max:
            remaining_pairs.append((a, b))

    # Now solve recursively for the remaining pairs

    # Sort remaining pairs by the first element
    remaining_pairs.sort()

    # Find the new max index (it should be the max of the remaining elements)
    if remaining_pairs:
        new_max_index = max(x for pair in remaining_pairs for x in pair)
    else:
