def max_sum_squared_distance(n, r):
    # Generate all integer points within or on the circle of radius r
    points = [(x, y) for x in range(-r, r + 1) for y in range(-r, r + 1) if x*x + y*y <= r*r]

    # Brute-force with memoization (tracking which points we've used)
    best_sum = -1
    best_points = []

    # Memoization dictionary
    memo = {}

    def try_combination(current_points, used_indices):
        nonlocal best_sum, best_points

        # If we have selected n points, update best
        if len(current_points) == n:
            s = 0
            # Calculate sum of squared distances
            for i in range(n):
                for j in range(i + 1, n):
                    dx = current_points[i][0] - current_points[j][0]
                    dy = current_points[i][1] - current_points[j][1]
                    s += dx*dx + dy*dy

            if s > best_sum:
                best_sum = s
                best_points = current_points[:]
            return

        # Try placing the same point again (at least once)
        if current_points:
            last_index = used_indices[-1]
            if current_points[-1] == points[last_index]:
                # Don't place the same point three times in a row
                if len(used_indices) > 1 and last_index == used_indices[-2]:
                    pass
                else:
                    new_used = used_indices + [last_index]
                    new_points = current_points + [current_points[-1]]
                    try_combination(new_points, new_used)

        # Try placing a new point
        for i in range(len(points)):
            if i == used_indices[-1]:
                continue  # Skip if placing the same point consecutively

            new_used = used_indices + [i]
            new_points = current_points + [points[i]]
            try_combination(new_points, new_used)

    try_combination([], [])
    return best_sum, best_points

