import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Separate evens and odds
    evens = []
    odds = []

    for num in a:
        if num % 2 == 0:
            evens.append(num)
        else:
            odds.append(num)

    # Sort evens and odds to get smallest first
    evens.sort()
    odds.sort()

    # Result array
    result = []

    # For each element in original array, place the smallest possible number
    # that can be swapped to this position
    for num in a:
        if num % 2 == 0:  # Even, want to place smallest odd
            if odds:
                result.append(odds.pop(0))
            else:
                result.append(num)
        else:  # Odd, want to place smallest even
            if evens:
                result.append(evens.pop(0))
            else:
                result.append(num)

    # Output
    sys.stdout.write(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
"}

