def find_available_day(start, duration, busy_days):
    """Find the earliest day x such that [x, x+duration-1] are all idle."""

    # First, check if we can use the preferred start day
    for day in range(start, start + duration):
        if day in busy_days:
            break
    else:
        # All days from start to start+duration-1 are idle
        return start

    # If not available, find the earliest x such that [x, x+duration-1] are idle
    for x in range(1, start + duration + 1):
        # Check if [x, x+duration-1] are all idle
        is_available = True
        for day in range(x, x + duration):
            if day in busy_days:
                is_available = False
                break
        if is_available:
            return x

    # If still not found, we need to scan further
    for day in range(start + duration, start + duration + 1000):
        for x in range(day, day + duration + 1):
            # Check if [x, x+duration-1] are all idle
            is_available = True
            for check_day in range(x, x + duration):
                if check_day in busy_days:
                    is_available = False
                    break
            if is_available:
                return x

    # If we get here, we didn't find anything, which shouldn't happen
    return start


n = int(input())
requests = []
for _ in range(n):
    s, d = map(int, input().split())
    requests.append((s, d))

busy_days = set()
results = []

for s, d in requests:
    # Check if we can use the preferred start day
    can_use = True
    for day in range(s, s + d):
        if day in busy_days:
            can_use = False
            break

    if can_use:
        # Use the preferred start day
        start = s
        end = s + d - 1
        busy_days.update(range(start, end + 1))
        results.append((start, end))
    else:
        # Find the earliest available day
        start = find_available_day(s, d, busy_days)
        end = start + d - 1
        busy_days.update(range(start, end + 1))
        results.append((start, end))

for start, end in results:
