def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

# Compute GCD of a list
def list_gcd(lst):
    return reduce(gcd, lst)

# Read input
n = int(input())
elements = list(map(int, input().split()))

# Compute GCD of all elements
gcd_value = list_gcd(elements)

# Divide all elements by GCD
elements //= gcd_value

# Count number of elements
num_elements = n

# Determine winner
if num_elements % 2 == 0:
    print("Alice")
elif num_elements % 2 == 1:
    print("Bob")
