import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    res = []
    ptr = 1
    for _ in range(t):
        n = int(data[ptr]); ptr += 1
        s = data[ptr]; ptr += 1
        # target1: 0 at even indices (0-indexed)
        mismatch1 = 0
        cnt1 = 0
        for i in range(n):
            if s[i] != str(i % 2):
                if mismatch1 == 0:
                    cnt1 += 1
                mismatch1 = 1
            else:
                mismatch1 = 0
        # target2: 1 at even indices (i%2 == 0 => 1, else 0)
        mismatch2 = 0
        cnt2 = 0
        for i in range(n):
            if s[i] != str(1 - (i % 2)):
                if mismatch2 == 0:
                    cnt2 += 1
                mismatch2 = 1
            else:
                mismatch2 = 0
        res.append(str(min(cnt1, cnt2)))
    sys.stdout.write("\n".join(res))

if __name__ == "__main__":
    solve()
