    # For an alternating string, either:
    # - 0 at even positions and 1 at odd positions, or
    # - 1 at even positions and 0 at odd positions

    # Count mismatches for both patterns
    mismatches_pattern1 = 0  # 0 at even indices
    for i in range(n):
        if i % 2 == 0 and s[i] != '0':
            mismatches_pattern1 += 1
        elif i % 2 == 1 and s[i] != '1':
            mismatches_pattern1 += 1

    mismatches_pattern2 = 0  # 1 at even indices
    for i in range(n):
        if i % 2 == 0 and s[i] != '1':
            mismatches_pattern2 += 1
        elif i % 2 == 1 and s[i] != '0':
            mismatches_pattern2 += 1

    # The minimum operations needed is half the minimum number of mismatches
    # because each operation can fix two mismatches at once
    min_operations = min(mismatches_pattern1, mismatches_pattern2) // 2

    print(min_operations)
