MOD = 10**9 + 7

# Precompute factorials and inverse factorials modulo MOD
def solve():
    max_n = 10**6 + 100
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact = [1] * (max_n + 1)
    inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
    for i in range(max_n-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    # Combination C(n, k) modulo MOD
    def comb(n, k):
        if n < 0 or k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    q = int(input())
    out_lines = []

    for _ in range(q):
        x, y = map(int, input().split())

        # Get prime factorization of x
        def factorize(x):
            factors = {}
            if x % 2 == 0:
                cnt = 0
                while x % 2 == 0:
                    x //= 2
                    cnt += 1
                factors[2] = cnt

            i = 3
            while i * i <= x:
                if x % i == 0:
                    cnt = 0
                    while x % i == 0:
                        x //= i
                        cnt += 1
                    factors[i] = cnt
                i += 2

            if x > 1:
                factors[x] = 1
            return factors

        prime_factors = factorize(x)

        result = 1
        for prime, exp in prime_factors.items():
            # Number of ways to distribute exp exponents among y factors
            ways = comb(exp + y - 1, y - 1)
            result = result * ways % MOD

        # Multiply by 2^(y-1) for sign variations
        result = result * pow(2, y-1, MOD) % MOD

        out_lines.append(str(result))

    print("\n".join(out_lines))

if __name__ == "__main__":
    solve()
