n = int(input())
cells_per_row = list(map(int, input().split()))

# Read the table
original_table = []
total_cells = sum(cells_per_row)

for i in range(n):
    row = list(map(int, input().split()))
    original_table.append(row)

# Collect all numbers and sort them
all_numbers = []
for row in original_table:
    all_numbers.extend(row)

all_numbers.sort()

# Create result table
result_table = []
for i in range(n):
    row = [0] * cells_per_row[i]
    result_table.append(row)

# Place sorted numbers in row-major order
index = 0
for i in range(n):
    for j in range(cells_per_row[i]):
        result_table[i][j] = all_numbers[index]
        index += 1

# Output the swaps
# We need to swap numbers from original to result
# Let's track positions that need swapping
swaps = []

# Create a mapping from number to position
num_to_pos = {}
for i in range(n):
    for j in range(cells_per_row[i]):
        num_to_pos[original_table[i][j]] = (i + 1, j + 1)

# Create a mapping from number to position in result
num_to_pos_result = {}
for i in range(n):
    for j in range(cells_per_row[i]):
        num_to_pos_result[result_table[i][j]] = (i + 1, j + 1)

# Find which numbers are in correct position
for i in range(n):
    for j in range(cells_per_row[i]):
        num = original_table[i][j]
        if num == result_table[i][j]:
            # Already correct
            pass
        else:
            # Need to swap
            swaps.append(
                (i + 1, j + 1, num_to_pos_result[num][0], num_to_pos_result[num][1])
            )

print(len(swaps))
for swap in swaps:
    print(*swap)
