import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    index = 1
    wins = [0] * (n + 1)  # 1-indexed

    # Read all games
    total_games = n * (n - 1) // 2
    games_read = 0

    while games_read < total_games - 1 and index < len(data):
        x = int(data[index])
        y = int(data[index + 1])
        wins[x] += 1
        index += 2
        games_read += 1

    # Find the missing game
    for i in range(1, n + 1):
        if wins[i] == n - 1:
            # i has already won all their games
            winner = i
            break
    else:
        # No one has won all their games yet
        # Find the participant with the most wins who hasn't won all games
        winner = 1
        max_wins = 0
        for i in range(1, n + 1):
            if wins[i] > max_wins and wins[i] < n - 1:
                winner = i
                max_wins = wins[i]

    for i in range(1, n + 1):
        if i != winner and wins[i] == n - 1:
            # i has already won all their games except the missing one
            loser = i
            break
    else:
        # Find the participant with the least wins who hasn't lost all games
        loser = 1
        min_wins = n - 1
        for i in range(1, n + 1):
            if i != winner and wins[i] < min_wins and wins[i] > 0:
                loser = i
                min_wins = wins[i]

    print(winner, loser)

if __name__ == "__main__":
    solve()
