def count_moves(n, s):
    from collections import Counter

    # Count occurrences of each character
    counts = Counter(s)

    # DP[i][prev_char][cnts] = min_swaps
    # We'll use a dictionary for counts
    from functools import lru_cache

    # Map characters to indices (0 for 'A', ..., 25 for 'Z')
    def char_to_idx(c):
        return ord(c) - ord('A')

    # Map indices to characters
    def idx_to_char(i):
        return chr(ord('A') + i)

    # Convert counts to tuple for use in lru_cache
    def counts_to_tuple(counts):
        return tuple(counts[i] for i in range(26))

    # Convert tuple back to counts
    def tuple_to_counts(tup):
        return [tup[i] for i in range(26)]

    # Get the current character at position pos (0-indexed)
    # Actually we need the original string to know which characters are at each position
    # But wait, we're rearranging the characters, so we need to know which characters are
    # available at each step

    # Instead, we'll just count how many characters of each type we have left

    @lru_cache(maxsize=None)
    def dp(pos, prev_char_idx, counts):
        # If we've placed all n characters, return 0
        if pos == n:
            return 0

        min_swaps = float('inf')

        # Try placing each character that we still have
        for c_idx in range(26):
            if counts[c_idx] == 0:
                continue

            # Check if placing this character is valid
            if prev_char_idx == ord('K') - ord('A') and c_idx == ord('V') - ord('A'):
                # 'K' followed by 'V' is valid
                pass
            elif prev_char_idx == ord('V') - ord('A') and c_idx == ord('K') - ord('A'):
                # 'V' followed by 'K' is invalid
                continue
            else:
                # Other cases are valid
                pass

            # Calculate cost: number of already placed characters that are 'greater'
            # already_placed = sum(counts) - counts[c_idx]  # total characters placed so far
            # But we need to count how many characters > c_idx are already placed
            cost = 0
            for idx in range(c_idx + 1, 26):
                if counts[idx] > 0:
                    cost += 1

            # Now update counts
            new_counts = list(counts)
            new_counts[c_idx] -= 1

            # Recursively get the minimum swaps for the next position
            result = dp(pos + 1, c_idx, tuple(new_counts))

            if result + cost < min_swaps:
                min_swaps = result + cost

        return min_swaps

    # Initial state: position 0, no previous character, all characters available
    initial_counts = tuple([0] * 26)
    for c in s:
        initial_counts[char_to_idx(c)] += 1

    return dp(0, -1, initial_counts)

n = int(input())
s = input().strip()

result = count_moves(n, s)
print(result)
