def solve():
    n, m, k = map(int, input().split())
    a = list(map(int, input().split()))

    # Store rules in a dictionary
    rules = {}
    for _ in range(k):
        x, y, c = map(int, input().split())
        rules[(x-1, y-1)] = c  # 0-indexed

    # dp[mask][last] = max satisfaction
    # mask has m bits set, last is the last dish in the sequence
    from collections import defaultdict

    dp = [defaultdict(int) for _ in range(1 << n)]

    # Initialize: single dishes
    for dish in range(n):
        mask = 1 << dish
        dp[mask][dish] = a[dish]

    # Build up solutions
    for mask in range(1 << n):
        if bin(mask).count('1') != m:
            continue

        # Try all last dishes in this mask
        for last in dp[mask]:
            current_satisfaction = dp[mask][last]

            # Try adding a new dish
            for new_dish in range(n):
                if not (mask & (1 << new_dish)):
                    new_mask = mask | (1 << new_dish)
                    new_satisfaction = current_satisfaction + a[new_dish]

                    # Check if we have a rule for last -> new_dish
                    if (last, new_dish) in rules:
                        new_satisfaction += rules[(last, new_dish)]

                    if new_satisfaction > dp[new_mask][new_dish]:
                        dp[new_mask][new_dish] = new_satisfaction

    # Find the best solution with exactly m dishes
    result = max(dp[(1 << m) - 1].values())
    print(result)

