import sys
import math

def range_min_sparse_table(matrix, n, m):
    """
    Build a 2D sparse table for range minimum query (RMQ).
    sparse_table[i][j] = min index in the submatrix starting at (i, j)
    """
    # Build sparse table for rows
    # row_sparse[i][j] = min index in row i starting at column j
    row_sparse = [[0] * (m + 1) for _ in range(n)]
    for i in range(n):
        row_sparse[i][m] = -1
        for j in range(m - 1, -1, -1):
            if matrix[i][j] <= matrix[i][j + 1]:
                row_sparse[i][j] = j
            else:
                row_sparse[i][j] = row_sparse[i][j + 1]

    # Build sparse table for columns
    # col_sparse[j][i] = min index in column j starting at row i
    col_sparse = [[0] * (n + 1) for _ in range(m)]
    for j in range(m):
        col_sparse[j][n] = -1
        for i in range(n - 1, -1, -1):
            if matrix[i][j] <= matrix[i + 1][j]:
                col_sparse[j][i] = i
            else:
                col_sparse[j][i] = col_sparse[j][i + 1]

    # Build 2D sparse table
    # sparse_table[i][j] = min index in rectangle (i, j) to (i+2^k-1, j+2^l-1)
    # Actually, we'll use row and column minima to query
    sparse_table = [[(0, 0)] * (m + 1) for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if i == n - 1 and j == m - 1:
                sparse_table[i][j] = (i, j)
            else:
                # Find minimum in rectangle starting at (i, j)
                min_idx = sparse_table[i][j]
                if matrix[i][j] <= matrix[i + 1][j]:
                    min_idx = (i, j)
                if matrix[i][j] <= matrix[i][j + 1]:
                    min_idx = (i, j)
                else:
                    min_idx = min(min_idx, (i, j + 1))
                if matrix[i][j] <= matrix[i + 1][j + 1]:
                    min_idx = (i, j)
                else:
                    min_idx = min(min_idx, (i + 1, j + 1))
                sparse_table[i][j] = min_idx

    return sparse_table

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n, m, a, b = map(int, data[:4])
    g0, x, y, z = map(int, data[4:8])

    # Generate matrix
    matrix = [[0] * m for _ in range(n)]
    g = g0
    for i in range(n):
        for j in range(m):
            matrix[i][j] = g
            g = (g * x + y) % z

    # Build sparse table
    sparse_table = range_min_sparse_table(matrix, n, m)

    # Compute answer
    answer = 0
    for i in range(n - a + 1):
        for j in range(m - b + 1):
            min_idx = sparse_table[i][j]
            answer += matrix[min_idx[0]][min_idx[1]]

    print(answer)

