        n = int(next(it))
        m = int(next(it))
        a = int(next(it))
        b = int(next(it))

        # Create two parent arrays (1-indexed)
        parent_a = [i for i in range(n + 1)]
        parent_b = [i for i in range(n + 1)]

        # For each vertex, we need to find its component when a is removed and when b is removed
        # So we'll build a graph without a, and without b, and find connected components

        # Build graph without a
        graph_a = [[] for _ in range(n + 1)]
        for _ in range(m):
            u = int(next(it))
            v = int(next(it))
            if u != a and v != a:
                graph_a[u].append(v)
                graph_a[v].append(u)

        # Build graph without b
        graph_b = [[] for _ in range(n + 1)]
        for _ in range(m):
