            v = int(next(it))
            if u != b and v != b:
                graph_b[u].append(v)
                graph_b[v].append(u)

        # Find components for graph without a
        for i in range(1, n + 1):
            if i != a:
                if find(parent_a, i) != i:
                    continue
                # DFS to find component
                stack = [i]
                comp = set()
                comp.add(i)
                while stack:
                    u = stack.pop()
                    for v in graph_a[u]:
                        if v != a and find(parent_a, v) == v and v not in comp:
                            comp.add(v)
                            parent_a[v] = i
                            stack.append(v)

        # Find components for graph without b
        for i in range(1, n + 1):
            if i != b:
                if find(parent_b, i) != i:
