import sys

def solve():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if line == "start":
            # Binary search: find smallest x where (x mod a) >= (x+1 mod a)
            # This means a = x+1
            x = 1
            while True:
                print(f"? {x} {x + 1}")
                sys.stdout.flush()
                res = sys.stdin.readline().strip()
                if res == "x":
                    # a = x+1
                    print(f"! {x + 1}")
                    sys.stdout.flush()
                    break
                elif res == "y":
                    x += 1
                else:
                    print("end")
                    sys.stdout.flush()
                    break
        elif line == "end":
            break
        elif line == "mistake":
            break

if __name__ == "__main__":
    solve()
