def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    points = []
    for _ in range(n):
        x = int(next(it))
        y = int(next(it))
        points.append((x, y))
    w = [int(next(it)) for _ in range(n)]

    # Frequency of each special value
    freq = {}
    for x, y in points:
        s = y - x
        freq[s] = freq.get(s, 0) + 1

    # Check if the frequency matches the required sequence
    count = {}
    for v in w:
        count[v] = count.get(v, 0) + 1

    if freq != count:
        print("NO")
        return

    # Sort points by (x + y) - this helps with partial order
    # Within same (x + y), sort by (x, y) to break ties
    points.sort(key=lambda p: (p[0] + p[1], p[0], p[1]))

    # We need to assign numbers such that if p1 ≤ p2, then num(p1) ≤ num(p2)
    # This is a topological sort problem

    # Let's use a greedy approach based on special values
    # We'll process points in order of increasing (x + y)

    # Create a list of points with their special value
    indexed_points = []
    for i, (x, y) in enumerate(points):
        indexed_points.append((x, y, y - x))

    # Now assign numbers
    result = [None] * n
    assigned = []  # list of points that have been assigned

    for i, (x, y, s) in enumerate(indexed_points):
        # Find the smallest available number
        num = available[0]

        # Check if this point can be assigned number num
        # It can if no previously assigned point dominates it
        dominated = False
        for x2, y2, s2 in assigned:
            if x2 >= x and y2 >= y:
                dominated = True
                break

        if not dominated:
            result[num - 1] = (x, y)
            assigned.append((x, y, s))
            available.pop(0)
            if not available:
                break

    if len(assigned) != n:
        print("NO")
    else:
        s_result = [y - x for x, y in result]
        if s_result != w:
            print("NO")
        else:
            print("YES")
