    else:
        S -= a[i] - b[i]

# Function to compute minimum f(j)
def min_f(S, n, m):
    if n % 2 == 0:
        # Even n: minimum is |S|
        return abs(S)
    else:
        # Odd n: f(j) = |S + j|
        # We want to minimize |S + j| over 0 <= j <= m - n
        # The minimum value is 0 if we can choose j = -S
        if -S >= 0 and -S <= m - n:
            return 0
        else:
            # Try values around -S
            return min(abs(-S), abs(1 - S), abs(m - n - S))

# Output initial minimum
print(min_f(S, n, m))

# Process updates
# We use a difference array for range updates
