def can_get_v(n, k, v, a):

    # Try transferring from one tank to another
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            # Transfer from i to j
            amount = min(a[i], k)
            new_a_i = a[i] - amount
            new_a_j = a[j] + amount

            # Check if we can get v in i or j
            if new_a_i == v:
                return True, f"1 {i+1} {j+1}"
            if new_a_j == v:
                return True, f"1 {j+1} {i+1}"

    # Try transferring from two tanks to one tank
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            # Transfer from i to j first
            amount1 = min(a[i], k)
            temp_a_i = a[i] - amount1
            temp_a_j = a[j] + amount1

            # Then transfer from temp_j (which is tank j now) to some other tank
            for k in range(n):
                if k == j:
                    continue
                amount2 = min(temp_a_j, k)
                new_a_i = temp_a_i
                new_a_j = temp_a_j - amount2
                new_a_k = a[k] + amount2

                # Check if we can get v in i, j, or k
                if new_a_i == v or new_a_j == v or new_a_k == v:
                    # This is actually 2 operations: i->j, then j->k
                    return True, f"1 {i+1} {j+1}\n1 {j+1} {k+1}"

    # Try transferring from three tanks to one tank (maybe the base case of 2 transfer)
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            for k in range(n):
                if k == j:
                    continue
                # Transfer from i to j
                amount1 = min(a[i], k)
                temp_a_i = a[i] - amount1
                temp_a_j = a[j] + amount1

                # Transfer from temp_j to k
                amount2 = min(temp_a_j, k)
                temp_a_j = temp_a_j - amount2
                temp_a_k = a[k] + amount2

                # Check if we can get v in i, j, or k
                if temp_a_i == v or temp_a_j == v or temp_a_k == v:
                    return True, f"1 {i+1} {j+1}\n1 {j+1} {k+1}"

    # Finally, check if we can just empty a tank (get 0)
    for i in range(n):
        cnt = (a[i] + k - 1) // k  # ceil(a[i] / k)
        result = f"{cnt} {i+1} 1"
        return True, result

    return False, "NO"

