        s = sys.stdin.readline().strip()

        # Simulate the robot's path without obstacles
        x, y = 0, 0
        path = [(x, y)]

        for move in s:
            if move == 'L':
                x -= 1
            elif move == 'R':
                x += 1
            elif move == 'D':
                y -= 1
            elif move == 'U':
                y += 1

            path.append((x, y))

        # Find the final position
        final_x, final_y = path[-1]

        # Try to find an obstacle position
        found = False
        obstacle_x, obstacle_y = 0, 0

        # We want to find a position (x, y) such that placing an obstacle there
        # changes the robot's path so it ends at (0, 0)

        # The idea is to find a position that the robot passes through
        # and then sees if we can find a way to cancel out the rest of the movement

        # Try all positions in the path (except start)
        for i in range(1, len(path)):
            pos = path[i]
            x, y = pos

            # Simulate with obstacle at pos
            curr_x, curr_y = 0, 0
            blocked = False

            for j, move in enumerate(s):
                if (curr_x, curr_y) == pos:
                    # Already at the obstacle position, it's blocked
                    continue

                if move == 'L':
                    curr_x -= 1
                elif move == 'R':
                    curr_x += 1
                elif move == 'D':
                    curr_y -= 1
                elif move == 'U':
                    curr_y += 1

                # Check if we just moved into the obstacle position
                if (curr_x, curr_y) == pos:
                    # If we just moved into the obstacle, we're blocked
                    curr_x, curr_y = pos
                    blocked = True

            if (curr_x, curr_y) == (0, 0):
                found = True
                obstacle_x, obstacle_y = x, y
                break

        if found:
            results.append(f"{obstacle_x} {obstacle_y}")
        else:
            results.append("0 0")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
