for d in digits:
    count[d] += 1

# DP matrix: size x x x
# T[i][j] = number of ways to go from state j to state i in one block
T = [[0] * x for _ in range(x)]
for d in range(1, 10):
    if count[d] == 0:
        continue
    for i in range(x):
        new_remainder = (i * 10 + d) % x
        T[new_remainder][i] += count[d]

# Matrix exponentiation to raise to b-th power
# We need T^b [k][0] (starting from state 0, ending in state k)

# Helper function for matrix multiplication
def mat_mult(a, b):
    result = [[0] * x for _ in range(x)]
    for i in range(x):
        for k_mid in range(x):
            if a[i][k_mid] == 0:
                continue
            for j in range(x):
                result[i][j] = (result[i][j] + a[i][k_mid] * b[k_mid][j]) % (10**9 + 7)
    return result

# Helper function for matrix exponentiation
def mat_pow(mat, power):
    # Initialize result as identity matrix
    result = [[0] * x for _ in range(x)]
    for i in range(x):
        result[i][i] = 1

    while power > 0:
        if power % 2 == 1:
            result = mat_mult(result, mat)
        mat = mat_mult(mat, mat)
        power //= 2
    return result

# Raise transition matrix to b-th power
final = mat_pow(T, b)

# Answer is final[k][0]
print(final[k][0])
