        bonuses[(x-1, y-1)] = c  # 0-indexed

    # DP: dp[used][last][pos] = max satisfaction
    # where used is bitmask of dishes used,
    # last is the last dish used (0-indexed),
    # pos is the number of dishes selected so far
    #
    # Since m <= n <= 18, we need 2^18 = 262,144 states
    # and m <= 18, so we need 19 positions
    #
    # We'll use a dictionary for DP
    dp = {}  # dp[mask][last] = max_satisfaction

    # Initialize: select one dish
    for i in range(n):
        mask = 1 << i
        dp[mask] = {i: a[i]}

    # Build up by adding one dish at a time
    for pos in range(1, m):
        new_dp = {}
        for mask in dp:
            for last in dp[mask]:
                current_satisfaction = dp[mask][last]

                # Try adding a new dish
                for i in range(n):
                    if not (mask & (1 << i)):
                        new_mask = mask | (1 << i)

                        # Calculate bonus if last dish is adjacent to i
                        bonus = bonuses.get((last, i), 0)
                        new_satisfaction = current_satisfaction + a[i] + bonus

                        key = (new_mask, i)
                        if key not in new_dp:
                            new_dp[key] = new_satisfaction
                        else:
