from collections import Counter
from bisect import bisect_right

def solve():
    n = int(input())
    balls = list(map(int, input().split()))
    balls.sort()

    # Precompute for each (i, j) the number of (x, y) with x < i, y < j, x + y = s
    freq = [Counter() for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, n+1):
            for x in range(i):
                for y in range(j):
                    s = balls[x] + balls[y]
                    freq[i][j][s] += 1

    # Precompute prefix sums for each (i, j, k) the number of (x, y, z) with x < i, y < j, z > k, x+y+z > i+j+k
    cnt = [[Counter() for _ in range(n+1)] for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, n+1):
            for x in range(i):
                for y in range(j):
                    s = balls[x] + balls[y]
                    for k in range(n):
                        for z in range(k+1, n):
                            if balls[x] + balls[y] + balls[z] > balls[i-1] + balls[j-1] + balls[k]:
                                cnt[i][j][k][s + balls[z]] += 1

    # Count favorable outcomes
    favorable = 0
    for a1 in range(n):
        for a2 in range(n):
            for a3 in range(n):
                sum_andrew = balls[a1] + balls[a2] + balls[a3]
                for j1 in range(a1):
                    for j2 in range(a2):
                        for j3 in range(n):
                            if balls[j3] > balls[a3] and balls[j1] + balls[j2] + balls[j3] > sum_andrew:
                                favorable += 1

    # Total valid outcomes
    total = n * (n-1) * n * (n-1) * n * (n-1)

    print(favorable / total)

solve()
