def solve():
    n = int(input())
    pairs = []
    for _ in range(n - 1):
        a, b = map(int, input().split())
        pairs.append((a, b))

    # Sort pairs by the larger index (b)
    pairs.sort(key=lambda x: x[1])

    # If the largest pair doesn't have n as the larger index, it's impossible
    if pairs[-1][1] != n:
        print("NO")
        return

    # Build the tree
    tree = [[] for _ in range(n + 1)]

    # We'll use a union-find approach
    parent = list(range(n + 1))

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        pu, pv = find(u), find(v)
        if pu == pv:
            return False
        parent[pu] = pv
        return True

    for a, b in pairs:
        # Try to connect a and b
        if not union(a, b):
            print("NO")
            return

    # Reconstruct the tree edges
    edges = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if find(i) == find(j):
                edges.append((i, j))
                break

    # Check if we have exactly n-1 edges
    if len(edges) != n - 1:
        print("NO")
        return

    print("YES")
    for u, v in edges:
        print(u, v)

