    total = sum(a) + m
    min_k = total // n
    if total % n != 0:
        min_k += 1

    benches = sorted([(val, i) for i, val in enumerate(a)])

    for val, i in benches:
        if val >= min_k:
            break
        needed = min_k - val
        if needed <= m:
            m -= needed
        else:
