n = int(input())
games = []

# Read all games
games = []
while len(games) < n * (n - 1) // 2 - 1:
    x, y = map(int, input().split())
    games.append((x, y))

# Count how many games each participant has participated in
count = [0] * (n + 1)
for x, y in games:
    count[x] += 1
    count[y] += 1

# Find the two participants who are missing one game
missing = [i for i in range(1, n + 1) if count[i] == n - 2]
a, b = missing

# Build a directed graph of who beats whom
g = {i: set() for i in range(1, n + 1)}
for x, y in games:
    g[x].add(y)

# Check if a beats b through a path
def has_path(from_node, to_node, g):
    visited = set()
    stack = [from_node]
    while stack:
        current = stack.pop()
        if current == to_node:
            return True
        if current not in visited:
            visited.add(current)
            for neighbor in g[current]:
                stack.append(neighbor)
    return False

if has_path(a, b, g):
    print(f"{a} {b}")
elif has_path(b, a, g):
    print(f"{b} {a}")
else:
    # If there's no path, we need to determine based on common comparisons
    # For all other participants, check if both have played against them
    common = []
    for i in range(1, n + 1):
        if i != a and i != b:
            if a in g[i] or i in g[a]:
                if b in g[i] or i in g[b]:
                    common.append(i)

    # Now we know who beats whom among common participants
    # If all common participants have played against a, then a should beat b
    # If all common participants have played against b, then b should beat a
    if all(b in g[i] or i in g[b] for i in common):
        print(f"{a} {b}")
elif all(a in g[i] or i in g[a] for i in common):
    print(f"{b} {a}")
else:
    # We don't know, but we can just output a and b in either order
    print(f"{a} {b}")
