import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    s = data[0]
    k = int(data[1])

    # Generate all substrings
    substrings = []
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            substrings.append(s[i:j])

    # Sort lexicographically
    substrings.sort()

    # Find the k-th substring
    if k <= len(substrings):
        print(substrings[k - 1])
    else:
        print("No such line.")

if __name__ == "__main__":
    solve()
"}

