int_count = words.count("int")
pair_count = words.count("pair")

if pair_count != int_count - 1:
    print("Error occurred")
else:
    # Build the type string
    stack = []
    result = []

    for word in words:
        if word == "int":
            result.append("int")
        elif word == "pair":
            stack.append(len(result))

    # Now add the punctuation
    for i, word in enumerate(words):
        if word == "int":
            result[i] = "int"
        elif word == "pair":
            # Find where this pair should be
            first_idx = stack.pop()
            second_idx = len(result)

            result[first_idx] = "pair<"
            result.insert(second_idx, ",")
            result.append(">")

    print("".join(result))
