def is_free(start, end, occupied):
    """Check if the interval [start, end] is free"""
    for (s, e) in occupied:
        if not (end < s or start > e):  # Overlap
            return False
    return True

def find_earliest(start, duration, occupied):
    """Find the earliest start day with duration consecutive free days"""
    # Try from day 1 up to start
    for x in range(1, start + 1):
        if is_free(x, x + duration - 1, occupied):
            return x

    # Try from day start + 1 onwards
    while True:
        x = start + 1
        if is_free(x, x + duration - 1, occupied):
            return x
        start += 1

